for i in ids:
    d=json.load(open('drafts/%s.json'%i))
    errs=[]
    if d['sourceFile']!=inp[i]['sourceFile']: errs.append('sourceFile mismatch')
    if d['id']!=i: errs.append('id')
    if d['primaryDomain'] not in d['domains']: errs.append('primary not in domains')
    for k,vals in [('domains','domains'),('audiences','audiences'),('sports','sports'),('populations','populations')]:
        for v in d[k]:
            if v not in tax[vals]: errs.append('bad %s: %s'%(k,v))
